  const open=items.filter(a=>a.status!=='Resolved'),esc=open.filter(a=>Object.keys(a.escalations||{}).length),resolvedToday=items.filter(a=>a.status==='Resolved'&&(a.resolvedAt||a.updated)>=day0);
