  const f=$('#em-f');f.onsubmit=async ev=>{ev.preventDefault();const v=new FormData(f);try{await api('email','PUT',{provider:v.get('provider'),apiKey:v.get('apiKey'),from:v.get('from'),fromName:v.get('fromName'),copyCustomers:v.has('copyCustomers')});toast('Saved');pages.emailPage(id);}catch(err){toast(err.message);}};
