 const host=document.querySelector('#main');host.insertAdjacentHTML('beforeend','<section class="card sites-panel" id="access-log"><div class="card-header"><div><h2>Account access activities</h2><p>Every staff sign-in and failed attempt, with the address it came from (latest 300).</p></div></div><p class="muted" style="padding:0 18px 16px">Loading…</p></section>');
