 for(const b of document.querySelectorAll('#detail-content [data-pf-reverse]'))b.onclick=()=>{$('#detail-dialog').close();radiusForm('Reverse payment '+b.dataset.ref,'Undoes this payment: removes the days and wallet credit it added, puts back any installation fee it settled and the points it earned. Use it for a payment recorded on the wrong account or one that bounced. Money is not sent back by this; use Refund afterwards if needed.',`<label>Reason<input name="reason" required minlength="4" maxlength="200"></label><label class="check-label"><input type="checkbox" name="rollbackExpiry" checked> Take back the days it added</label><label>Type ${H(b.dataset.ref)} to confirm<input name="confirm" required autocomplete="off"></label>`,'Reverse payment',inp=>api('payments/'+b.dataset.pfReverse+'/reverse','POST',{reason:inp.reason,confirm:inp.confirm,rollbackExpiry:inp.rollbackExpiry==='on'}).then(()=>{toast('Payment reversed');window.openProfile(id);}));};
