 api('speed-explain/'+id).then(e=>{const el=$('#pf-speed');if(el)el.innerHTML=`<strong>${e.downMbps} / ${e.upMbps} Mbps</strong>${e.fup?` <span class="status warning">fair-usage speed (${H(e.fup.reasons.join(', '))})</span>`:''}<ol class="pf-steps">${e.steps.map(x=>`<li>${H(x)}</li>`).join('')}</ol><small>${H(e.note)}</small>`;}).catch(()=>{});
